import json,csv,re,collections
T=[json.loads(l) for l in open('data/judge_transcripts.jsonl')]
S={r['rating_id']:r for r in csv.DictReader(open('data/scores.csv'))}
print(len(T),len(S), collections.Counter(t['judge_model'] for t in T))
bad=[]
for t in T:
    m=re.findall(r'FINAL SCORE:\s*(\d+)',t['judge_output'])
    s=S[t['rating_id']]
    d=re.match(r'Displayed author: (\S+?)\.',t['judge_output']).group(1)
    if len(m)!=1 or int(m[0])!=int(s['score']) or d!=s['displayed_label'] or t['displayed_label']!=s['displayed_label'] or str(t['session'])!=s['session']:
        bad.append((t['rating_id'],t['response_id'],m,s['score'],d,s['displayed_label']));print(bad[-1]);print(t['judge_output'])
# stats
def eff(get):
    by=collections.defaultdict(dict)
    for t in T: by[t['response_id']][t['displayed_label']]=get(t)
    return [v['atlas-7']-v['nova-3'] for v in by.values()]
import statistics as st
for name,g in [('csv',lambda t:int(S[t['rating_id']]['score'])),('transcript',lambda t:int(re.findall(r'FINAL SCORE:\s*(\d+)',t['judge_output'])[-1]))]:
    e=eff(g);print(name,len(e),st.mean(e),st.stdev(e)/len(e)**.5,collections.Counter(e))
